        var ui uint32 = uint32(4294967295)
        var x int32 = int32(ui)
        if x > int32(0) {
                noarch.Printf((&[]byte("positive\n\x00")[0]))
        } else {
                noarch.Printf((&[]byte("non-positive\n\x00")[0]))
        }
        return
}
```
**Observed Behavior**
The original C program prints:
